window.L5R_CHARACTER = {"slug":"nasu-kogo","name":"Nasu Kogo","clan":"Phoenix","family":"Nasu","region":null,"upbringing":null,"origin_type":null,"school":"Shosuro Shadowweaver School","role":"Shugenja","bucket":"Shugenja","campaign":"The Bushi Oni","status":null,"accent":"#5b398e","portrait":"src/portraits/nasu-kogo.png","concept":null,"summary":null,"tier_count":4,"xp_min":0,"xp_max":63,"provenance":"archive","product":null,"twenty_questions":{"template":"core","generated":true,"steps":{"step1":{"answers":{"clan":"Phoenix","ring":"void","skill":"theology","social_status":30},"picks":{}},"step2":{"answers":{"family":"Nasu (Shiba Vassal)","ring":"water","skill1":"meditation","skill2":"tactics","wealth":5,"social_glory":40},"picks":{}},"step3":{"answers":{"school":"Shoshuro Shadoweaver School","roles":"Shugenja","ring1":"air","ring2":"fire","skill1":"courtesy","skill2":"government","skill3":"skulduggery","social_honor":30},"picks":{"techniques":["Prey on the Weak","Commune with the Spirits","By the Light of the Lord Moon","Cloak of Night","Fukurokujin’s Wit"],"school_ability":["Sudden Nightfall"],"equipment":["Concealed Armor","Sanctified Robes","Wakizashi","Shuriken","Poison (One Vial)","Tetsubishi"]}},"step4":{"answers":{"stand_out":"Kogo is experimental and creative in her work.","ring":"fire"},"picks":{}},"step5":{"answers":{"social_giri":"Her lord is Nasu Tadaaki, her own father and current head of the declining Nasu family. Her duty is to restore the family's status and influence with the Imperial families. Kogo must prove the Nasu worthy of their former position."},"picks":{}},"step6":{"answers":{"social_ninjo":"Kogo yearns for power that cannot be taken away by political whims or clan hierarchies. Deep down, she wants to transcend the petty limitations of clan politics entirely - to become something more than a samurai bound by duty and status."},"picks":{}},"step7":{"answers":{"clan_relations":"Publicly, Kogo is a dutiful daughter of the Phoenix, respectful of tradition and the Elemental Council. Privately, she seethes at how the clan's rigid hierarchies and spiritual purity have constrained her family's potential. She sees the Phoenix as hidebound, more concerned with ancient texts than real power, more worried about propriety than results.","skill":"sentiment","social_add_glory":0},"picks":{}},"step8":{"answers":{"bushido":"Kogo believes that the ends justify the means. Bushido matters mostly as a matter of what is observed; what is unobserved is not beholden.","skill":"skulduggery","social_add_honor":0,"tenet_paramount":" Duty and Loyalty","tenet_less_significant":"Compassion"},"picks":{}},"step9":{"answers":{"success":"During her final year at the Shosuro Shadowweaver School, Kogo uncovered a Lion Clan conspiracy against Scorpion trade interests in the capital. Rather than simply reporting it to her sensei, she manipulated the situation—feeding the conspirators false information while ensuring the Scorpion's countermove appeared as superior planning rather than intelligence work. In the process, she obtained compromising evidence against Akodo Nobuhiko, a Lion courtier stationed at Otosan Uchi, which she quietly kept for herself."},"picks":{"distinction":["Blackmail on [Name]"]}},"step10":{"answers":{"difficulty":"During her Scorpion training, Kogo discovered a hidden scroll tucked away in her sensei's private collection—a fragmentary document on forbidden techniques that she believes the Scorpion was saving for leverage. She copied it in secret, certain she was the first to read it in years, and the text spoke of power beyond the kami's limitations. The knowledge was intoxicating, and when she attempted the first technique described within, she succeeded—but something dark answered her call. She gained power, but also corruption she can never fully cleanse. The Shadowlands Taint now marks her spiritual essence, a constant reminder that she has stepped onto a path from which there may be no return."},"picks":{"adversity":["Shadowlands Taint (Air)"]}},"step11":{"answers":{"calms":"Despite her ambitions and resentments, Kogo finds genuine tranquility in the traditional tea ceremony. In those quiet, ritualized moments—the precise movements, the meditative focus, the temporary suspension of scheming and striving—she can almost forget her burdens."},"picks":{"passion":["Tea"]}},"step12":{"answers":{"worries":"Kogo lives in constant fear that her maho practice will be discovered before she achieves her goals, which would mean execution and her family's destruction. Worse still, she has become convinced that conspiracies surround her—that rival Phoenix families work to keep the Nasu marginalized, that the Scorpion suspect what she stole, that someone is always watching and waiting for her to slip. She sees patterns and plots in innocent coincidences, reads threat into casual questions, and trusts almost no one. Whether these conspiracies are real or products of her guilty conscience hardly matters; the paranoia shapes every decision she makes."},"picks":{"anxiety":["Conspiracy"]}},"step13":{"answers":{"most_learn":"Shiba Atsutane was assigned as Kogo's sponsor when she first arrived at Otosan Uchi—a well-meaning Phoenix courtier who was supposed to guide her entry into Imperial politics. Instead, she watched him destroy his own career within six months. Atsutane's fatal flaw was that he actually cared about the people affected by court decisions; he advocated too openly for the suffering, showed too much genuine emotion, and completely failed to read when powerful figures wanted problems ignored rather than solved. His compassion made him predictable, exploitable, and ultimately disposable. When he was quietly recalled to Phoenix lands in disgrace, Kogo stepped smoothly into his position—having learned that court is performance, that sincerity is a liability, and that compassion is a luxury for those who can afford to lose. She feels no sympathy for his fall; he had it coming, and she's more than happy to replace him.","skill":"performance"},"picks":{"disadvantage":["Disdain for Compassion"]}},"step14":{"answers":{"first_sight":"Where many would have their own scribes, she takes her own copious notes at all times, in an elegant personal cipher."},"picks":{"special_features":["Calligraphy Set"]}},"step15":{"answers":{"stress":"She organizes her spaces, demanding a complete sense of control over her environment."},"picks":{}},"step16":{"answers":{"relations":"Kogo maintains a careful relationship with Bayushi Toshiro, a mid-ranking Scorpion operative in Otosan Uchi who served as one of her instructors. He occasionally feeds her intelligence about court intrigues—partly because the Scorpion value having a Phoenix ally, partly because he enjoys keeping her in his debt.\n\nKogo has cultivated a relationship with the proprietress of the Plum Blossom Tea House, a neutral meeting ground for courtiers in Otosan Uchi. The woman, Usagi Hanako (a Hare Clan vassal family member), runs the establishment as a place where \"all are welcome to find peace\"—but she's also remarkably well-informed about court gossip and has helped Kogo navigate the capital's social waters."},"picks":{"item":["Personal Seal or Chop"]}},"step17":{"answers":{"parents_pov":"To Nasu Tadaaki, Kogo is \"the future of our family, the one who will reclaim our rightful place.\" He describes her with a mixture of pride and barely concealed desperation—she is his only child, his last chance to restore the Nasu name before he dies. He speaks of her accomplishments with fierce pride to anyone who will listen, perhaps too loudly, too insistently, as if he can will the world to recognize her worth through sheer force of repetition. Other nobles find his advocacy unseemly; Kogo finds it suffocating. The weight of being everything to him is crushing.","skill":"composition"},"picks":{}},"step18":{"answers":{"heritage_name":"Kogo was named after her aunt, Nasu Kogo the Elder, a talented performer and courtier who was considered the family's brightest star a generation ago. Two years ago, Aunt Kogo was invited to perform in an imperial theatrical production—a tremendous honor and exactly the kind of recognition the Nasu desperately needed. Instead, she delivered a catastrophically bad performance. Whether from nerves, illness, or simple misfortune, she forgot lines, missed cues, and finally froze entirely on stage. The Emperor himself left the theater in discomfort. The shame was so profound that Aunt Kogo took the tonsure and entered a monastery, but the damage was done—rumors spread that the Nasu family is cursed by Benten-no-kami for some forgotten slight against the arts. Young Kogo now carries not just her aunt's name, but the burden of redeeming it.","heritage_1":4,"heritage_2":9,"heritage_add_honor":0,"heritage_add_glory":0,"heritage_add_status":-3,"skill":"command"},"picks":{"heritage_item":["Benten’s Curse"]}},"step19":{"answers":{"firstname":"Kogo"},"picks":{}},"step20":{"answers":{"death":"When the Nasu name has finally been restored to its rightful place among the Phoenix—when her father has seen his family honored once more, when the whispers of curses have been replaced with respect, when she has proven that will and ability matter more than bloodline—then and only then should Kogo die. She imagines herself at the pinnacle of her power, having mastered both legitimate magic and the forbidden arts, having achieved everything she set out to accomplish. In that moment of triumph, she would take her own life in a final act of control, silencing the kansen that whisper in her mind, severing the corruption before it can spread to others or taint her family's restored glory."},"picks":{}}}},"notes":"","bio":"","published":null,"demeanor":null,"relationships":null,"curriculum":[{"rank":1,"kind":"Skill Group","group":null,"label":"Social Skills","prereq":false},{"rank":1,"kind":"Skill","group":null,"label":"Fitness","prereq":false},{"rank":1,"kind":"Skill","group":null,"label":"Government","prereq":false},{"rank":1,"kind":"Skill","group":null,"label":"Martial Arts [Ranged]","prereq":false},{"rank":1,"kind":"Tech. Grp.","group":"shuji","label":"Rank 1 Shuji","prereq":true},{"rank":1,"kind":"Technique","group":"ninjutsu","label":"Skulk","prereq":true},{"rank":1,"kind":"Technique","group":"ninjutsu","label":"Deadly Sting","prereq":true},{"rank":2,"kind":"Skill Group","group":null,"label":"Scholar Skills","prereq":false},{"rank":2,"kind":"Skill","group":null,"label":"Courtesy","prereq":false},{"rank":2,"kind":"Skill","group":null,"label":"Martial Arts [Ranged]","prereq":false},{"rank":2,"kind":"Skill","group":null,"label":"Skulduggery","prereq":false},{"rank":2,"kind":"Tech. Grp.","group":"invocation","label":"Rank 1-2 Invocations","prereq":false},{"rank":2,"kind":"Technique","group":"invocation","label":"Fluid Shadows","prereq":false},{"rank":2,"kind":"Technique","group":"shuji","label":"Lord Bayushi’s Whispers (Scorpion)","prereq":true},{"rank":3,"kind":"Skill Group","group":null,"label":"Martial Skills","prereq":false},{"rank":3,"kind":"Skill","group":null,"label":"Government","prereq":false},{"rank":3,"kind":"Skill","group":null,"label":"Sentiment","prereq":false},{"rank":3,"kind":"Skill","group":null,"label":"Skulduggery","prereq":false},{"rank":3,"kind":"Tech. Grp.","group":"shuji","label":"Rank 1-3 Shuji","prereq":true},{"rank":3,"kind":"Technique","group":"invocation","label":"Dream Painter","prereq":false},{"rank":3,"kind":"Technique","group":"ninjutsu","label":"Noxious Cloud","prereq":true},{"rank":4,"kind":"Skill Group","group":null,"label":"Social Skills","prereq":false},{"rank":4,"kind":"Skill","group":null,"label":"Culture","prereq":false},{"rank":4,"kind":"Skill","group":null,"label":"Martial Arts [Ranged]","prereq":false},{"rank":4,"kind":"Skill","group":null,"label":"Theology","prereq":false},{"rank":4,"kind":"Tech. Grp.","group":"invocation","label":"Rank 1-4 Invocations","prereq":false},{"rank":4,"kind":"Technique","group":"shuji","label":"Wolf’s Proposal","prereq":true},{"rank":4,"kind":"Technique","group":"kata","label":"Pin the Fan","prereq":true},{"rank":5,"kind":"Skill Group","group":null,"label":"Martial Skills","prereq":false},{"rank":5,"kind":"Skill","group":null,"label":"Culture","prereq":false},{"rank":5,"kind":"Skill","group":null,"label":"Medicine","prereq":false},{"rank":5,"kind":"Skill","group":null,"label":"Skulduggery","prereq":false},{"rank":5,"kind":"Tech. Grp.","group":"shuji","label":"Rank 1-5 Shuji","prereq":true},{"rank":5,"kind":"Technique","group":"invocation","label":"The Fading Dream","prereq":false},{"rank":5,"kind":"Technique","group":"ninjutsu","label":"Silencing Stroke","prereq":true}],"title_curricula":{},"legacies":[],"tiers":[{"xp":0,"label":null,"rank":1,"school":"Shosuro Shadowweaver School","foundry_id":"1couuYrLcG6efybt","rings":{"air":2,"earth":1,"fire":3,"water":2,"void":2},"skills":{"artisan":{"aesthetics":0,"composition":1,"design":0,"smithing":0},"martial":{"fitness":0,"melee":0,"ranged":0,"unarmed":0,"meditation":1,"tactics":1},"scholar":{"culture":0,"government":1,"medicine":0,"sentiment":1,"theology":1},"social":{"command":1,"courtesy":1,"games":0,"performance":1},"trade":{"commerce":0,"labor":0,"seafaring":0,"skulduggery":2,"survival":0}},"social":{"honor":30,"glory":40,"status":27,"ninjo":"Kogo yearns for power that cannot be taken away by political whims or clan hierarchies. Deep down, she wants to transcend the petty limitations of clan politics entirely - to become something more than a samurai bound by duty and status.","giri":"Her lord is Nasu Tadaaki, her own father and current head of the declining Nasu family. Her duty is to restore the family's status and influence with the Imperial families. Kogo must prove the Nasu worthy of their former position.","bushido_tenets":{"paramount":" Duty and Loyalty","less_significant":"Compassion"}},"derived":{"endurance":8,"composure":6,"focus":5,"vigilance":2,"void_points":2},"money":{"zeni":0,"koku":5,"bu":0},"advancements":[],"techniques":[{"name":"Prey on the Weak","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"shuji","rank":2,"description":"<ul><li>Court is not a kind place, and a harsh word is no less cruel for being spoken softly and with perfect etiquette.</li><li>As a Scheme action, make a TN 1 Courtesy (Air) check targeting a Compromised character.</li><li>If you succeed, your target must choose one of the following: (1) Immediately unmask in a manner of their choosing based on the circumstances. (2) Forfeit glory equal to your Air Ring plus your bonus successes to leave the scene.</li><li>Air (op)+: If the target chooses to unmask, you learn one of their disadvantages of their choice per (op) spent this way.</li><li>Air (op)(op): If the target chooses to leave the scene, you notice their destination from the direction of their departure or overhear from the crowd where they will retreat.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":215},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.ekziVajOr3Up1EjP","skill":"courtesy"},{"name":"Commune with the Spirits","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"ritual","rank":1,"description":"<ul><li>The ritualist centers their mind on one of the Elements, appealing to the spirits in their environment and seeking their counsel or boon. Priests and laypeople are able to use this ritual to receive less specific guidance from the spirits, such as a leaf that falls to the ground pointing in the direction of the person or thing they are seeking.</li><li>As a downtime activity or Support action, make a TN 1 Theology check using Air, Earth, Fire, Water, or Void to appeal to nearby spirits of that Element (appeal to the departed, such as ancestor spirits, and other non-elemental supernatural presences if using Void) for aid.</li><li>If you succeed, choose and receive one of the following boons: (1) Sense the Kami — Detect all spirits and uses of their magic by shugenja within a number of range bands equal to the ring you used plus your bonus successes. (2) Spiritual Knowledge — Learn one fact the spirits know about the area. (3) Elemental Gift — The kami deliver a small amount of the Element in question to you (e.g., rain from water kami, sparks from fire kami, a gust from air kami, a stone from earth kami, or a found ancestor&#x27;s belonging from Void).</li><li>(op): Reduce the TN of your next check to interact with or appeal to kami or supernatural presences of this Element by 1.</li><li>(op)+: If you succeed, receive one additional boon per (op) spent this way. Each boon can only be received one time per activation.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":212},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-rituals-l5r-sortilege.Item.r9DyFb62vtLwexbW","skill":"theology"},{"name":"By the Light of the Lord Moon","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"invocation","rank":1,"description":"<ul><li>When a shugenja performs this invocation, the light shifts to that of a moonlit night, unweaving the shadows to lay bare the things they conceal. Hidden objects glow faintly with silver light, while mystical illusions are revealed as translucent, gossamer forms.</li><li>As a Scheme action, make a TN 2 Theology (Air) check targeting an area at range 0-2.</li><li>If you succeed, you scry for each hidden character and concealed object (secret compartments, trap doors, concealed weapons) in the targeted area, revealing it with a luminous outline only you can perceive. Only reveals mundane concealment.</li><li>Air +(op): Reveal up to one magically concealed object per (op) spent this way.</li><li>Air (op)(op)+: Choose one additional character at range 0-1 per (op)(op) spent this way who can also see the objects.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":192},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-invocations-l5r-sortilege.Item.X37l2OFmdoUXYJtX","skill":"theology"},{"name":"Cloak of Night","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"invocation","rank":1,"description":"<ul><li>A sufficiently learned shugenja can call forth air kami to play one of their simplest and most effective tricks: enveloping an object or person in their embrace to hide it from sight.</li><li>As a Scheme and Support action, make a Theology (Air) check targeting one object or character at range 0-1. TN equals the target&#x27;s Silhouette.</li><li>If you succeed, you augment the target with an illusion that renders it invisible to the naked eye. The object is still physically present and can be touched, smelled, or sensed with any normal sense other than vision. Persists for one round, plus additional rounds equal to your bonus successes.</li><li>Air (op)(op)+: Choose one additional target of the same silhouette or smaller per (op)(op) spent this way.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":192},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-invocations-l5r-sortilege.Item.fveOrp1xJ9uGnNCl","skill":"theology"},{"name":"Fukurokujin’s Wit","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"invocation","rank":1,"description":"<ul><li>Shujenja are scholars at their heart, for their art is one of long hours of study and dedication to the refinement of the mind. Thus, many seek the blessing of Fukurokujin, keeper of knowledge and patron to scholars. A shugenja can call upon the guidance of this Fortune to sharpen their mind to a razor edge and vitalize their nerves.</li><li>As a Support action, make a TN 1 Theology (Fire) check targeting yourself.</li><li>If you succeed, you augment your target&#x27;s wits and cunning. When making checks, the target adds a kept (ring) set to a (su) result. Persists for one round, plus additional rounds equal to bonus successes.</li><li>Fire (op): You may target another character at range 0-2 instead of yourself.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":203},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-invocations-l5r-sortilege.Item.bH76OcZ5FOcuLRXx","skill":"theology"},{"name":"Sudden Nightfall","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"school_ability","rank":1,"description":"<p>You do not suffer ill effects of Obscuring terrain from darkness. When you perform an Attack or Scheme action against a target in darkness-Obscuring terrain, reduce the TN by your school rank (minimum 1). As a Support action, summon supernatural darkness at range 0-2; area extending Air Ring range bands becomes Obscuring, persisting a number of rounds equal to school rank.</p>","text_source":"dsl","source":{"book":"celestial_realms","page":87},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.a06K6G42WcqlCnxQ"}],"peculiarities":[{"name":"Blackmail on Akodo Nobuhiko","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"fire","types":"Interpersonal","custom":true,"description":"<p><span class=\"fontstyle0\"><em>“I had hoped to find you here,” Yogo Hiroue began. “It has been too long since we last spoke plainly.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Blackmail on [Name] distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- You have incriminating information on an individual, which you use to force them to help you even when doing so may damage their reputation. They will share what knowledge they have about a given person, item, location, or situation, whether through a face-to-face meeting or through written correspondence. They will also arrange for introductions with exclusive members of society or places of business. Confer with the GM to select a campaign-appropriate NPC when choosing this advantage.</span></p></li><li><p><span class=\"fontstyle0\">- When performing a check to demand favors of the chosen individual (such as a Courtesy (fire) check to remind them of the consequences of their disobeying you or a Command (fire) check to order them to risk themself on your behalf), you may reroll up to two dice.</span></p></li></ul>","source_reference":{"source":"core_rulebook","page":102}},{"name":"Tea","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"passion","ring":"void","types":"Physical, Spiritual","description":"<ul><li>You can identify regional variations in tea, and you know a great deal about the process of preparing and drying leaves. In the wilderness, you can acquire the natural ingredients required to make rustic teas of various sorts with relative ease.</li><li>After performing a check to interact with tea (such as a Medicine [Void] check to brew a tea with ingredients that help the body recover from illness or a Performance [Void] check to perform a tea ceremony that helps the recipients contemplate their state in life), you remove 3 strife.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":115},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.wiz5rooMR3tqtULe"},{"name":"Shadowlands Taint (Air)","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"air","types":"Curse, Interpersonal, Spiritual","description":"<ul><li>You are a Tainted being. You have trouble sympathizing with other humans, but you can understand the emotions of corrupted beings easily.</li><li>When you make a check to show compassion for other human beings (such as a Composition [Air] check to edit a work for emotional refinement or a Courtesy [Air] check to say something difficult without harming the recipient&#x27;s feelings), you must choose and reroll two dice containing success or explosive success. After resolving the check, if you failed, you gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":127},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.eEg9b6rmnSBA5HqG"},{"name":"Conspiracy","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"anxiety","ring":"earth","types":"Interpersonal, Mental","description":"<ul><li>Plagued by knowledge of greater plots; you are constantly suspicious of authority figures.</li><li>After performing a check to interact with an unfamiliar authority figure, you receive 3 strife. If this is the first time this scene, gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"celestial_realms","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.wBeHgMqK2BL7fX6I"},{"name":"Disdain for Compassion","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"water","types":"Flaw, Mental","description":"<ul><li>Choose one tenet: Compassion (Water), Courage (Fire), Courtesy (Air), Duty and Loyalty (Earth), Honor (Void), Righteousness (Void), or Sincerity (Void). A character may have multiple instances of this disadvantage for different tenets. You no longer believe in the chosen tenet of Bushidō, though you still lose honor for disobeying it. When you act in accordance with this tenet of Bushidō, others can sometimes sense your insincerity.</li><li>When you make a check to pay lip service to this tenet of Bushidō or to uphold it (such as a Courtesy check to express its importance or a Meditation check to use a belief in this tenet to your advantage), you must choose and reroll two dice containing success or explosive success. After resolving the check, if you failed, you gain 1 Void point.</li></ul>","text_source":"dsl","text_via":"Disdain for a Bushidō Tenet","source":{"book":"core_rulebook","page":120},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.WLiIHkS6o7pS2u9y"},{"name":"Benten’s Curse","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"air","types":"Interpersonal, Spiritual","description":"<ul><li>Your romantic efforts are always stymied by circumstances, and your gestures to get the romantic attention of others are usually misinterpreted.</li><li>When you make a check to express your admiration to someone (such as an Aesthetics [Air] check to find the right poem to read to express your feelings or a Courtesy [Air] check to tell someone your feelings without exceeding propriety), you must choose and reroll two dice containing success or explosive success. After resolving the check, if you failed, you gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":116},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.wx0TwgTwrxGMVd1g"}],"titles":[],"bonds":[],"signature_scrolls":[],"gear":[{"name":"Wakizashi","quantity":1,"description":"<p>Whereas the katana represents a samurai’s status as a warrior, the wakizashi represents their place in Rokugan’s social order and strict caste system. The wakizashi is a small, katana-like sword usually two to three feet in length, with the same flexible blade and lethal edge. It is often made as part of a pair, with the same decorations as its matched katana. The wakizashi also fills another role: it clearly signals that its wearer is a samurai, and a person of honor who will make the ultimate sacrifice for their ideals and their master. It is the tool with which a samurai commits seppuku: ritual suicide, the last protest of an aggrieved and honorable samurai.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":233},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.S1MG4qPHEV3N8XnO","damage":3,"deadliness":5,"range":"0-1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"15 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Shuriken","quantity":6,"description":"<p>Favored by shinobi, shuriken are small metal discs with a sharpened edge that come in a dizzying array of sizes and styles. They are designed mainly to distract, but shuriken can also be coated with toxins for lethality, and any cutting edge can kill if used properly.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":237},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.5Lr1CNs1uvX7J38y","damage":2,"deadliness":4,"range":"0","grip_1":"(stab or slash): -, (thrown): Martial Arts [Ranged], Range 1-3","grip_2":"N/A","skill":"unarmed","category":"Specialist Weapons","rarity":"6","zeni":"1 koku","properties":[{"id":"L5RCorePro000005","name":"Concealable"}]},{"name":"Concealed Armor","quantity":1,"description":"<p>Used by cautious courtiers, shinobi, and anyone else who fears assassination, concealed armor is a kimono, keikogi, or other garment with thin bamboo or metal plates sewn inside to turn an unexpected blade or arrow.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.vDEAuVf0o5GwmVsB","armor":{"physical":2,"supernatural":0},"rarity":"4","zeni":"5 koku","properties":[{"id":"L5RCorePro000005","name":"Concealable"}]},{"name":"Sanctified Robes","quantity":1,"description":"<p>The vestments of shugenja, shrine keepers, and other religious figures are blessed by kami and thus grant mystical protection. Traditionally, such robes consist of a white garment called jōe (literally, “pure cloth”) and a peaked hat, but they can be simpler, such as a white haori top and red hakama bottoms, or even an elaborate kimono.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.Cq1koK56k9dvLfMh","armor":{"physical":1,"supernatural":3},"rarity":"7","zeni":"4 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"}]},{"name":"Poison (One Vial)","quantity":3,"description":"<p>In the courts of the Emerald Empire, the wheels of politics are sometimes turned by unsavory means. Members of the Scorpion Clan are certainly not above using poison to weaken or eliminate political rivals—not that one could ever prove their culpability—and many samurai turn to such measures in times of desperation or fear.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":244},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.SNTCLZ2aScPEddId","rarity":"5","zeni":"30 zeni","properties":[{"id":"L5RCorePro000009","name":"Forbidden"}]},{"name":"Tetsubishi","quantity":1,"description":"<ul><li>Category: Personal Effect</li><li>Cost: 5 bu per handful</li><li>Rarity: 4</li><li>As an Attack and Support action, a character may scatter a handful of tetsubishi targeting a patch of ground at range 0-2. The terrain at range 0-1 from the point of impact gains the Dangerous and Ensnaring terrain quality.</li></ul>","text_source":"dsl","source":{"book":"fields_of_victory","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.4OCDJyLlEF5F7feH","rarity":"4","zeni":"5 bu"},{"name":"Calligraphy Set","quantity":1,"description":"<p>These ornate boxes contain items a practiced callig- rapher needs to craft books, letters, scrolls, and other written communications. It consists of a small wooden box that contains a variety of brushes, inkstones, and pigments; a small bowl for water; and a small bag of sand for drying. Calligraphers and scribes customari- ly carry a calligraphy set, as so do some samurai and courtiers who prefer to write their own correspon- dence.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":242},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.MWzx5Wiu6xcCWc9J","rarity":"3","zeni":"1 bu"},{"name":"Personal Seal or Chop","quantity":1,"description":"<p>A personal chop is used by samurai to verify their iden- tity and sign documents, among other official business. Each one is a unique design that is registered with the Miya family. Using another samurai’s chop is consid- ered both an insult and a serious crime.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":243},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.UU5eQKPBQZ9ilOTF","rarity":"6","zeni":"4 bu","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"}]}],"gear_patterns":[]},{"xp":20,"label":"Rank 2","rank":2,"school":"Shosuro Shadowweaver School","foundry_id":"yQLM5kLHqFdrhfVd","rings":{"air":2,"earth":1,"fire":3,"water":2,"void":2},"skills":{"artisan":{"aesthetics":0,"composition":1,"design":0,"smithing":0},"martial":{"fitness":0,"melee":0,"ranged":0,"unarmed":0,"meditation":1,"tactics":1},"scholar":{"culture":0,"government":2,"medicine":0,"sentiment":1,"theology":1},"social":{"command":1,"courtesy":2,"games":0,"performance":1},"trade":{"commerce":0,"labor":0,"seafaring":0,"skulduggery":2,"survival":0}},"social":{"honor":30,"glory":40,"status":27,"ninjo":"Kogo yearns for power that cannot be taken away by political whims or clan hierarchies. Deep down, she wants to transcend the petty limitations of clan politics entirely - to become something more than a samurai bound by duty and status.","giri":"Her lord is Nasu Tadaaki, her own father and current head of the declining Nasu family. Her duty is to restore the family's status and influence with the Imperial families. Kogo must prove the Nasu worthy of their former position.","bushido_tenets":{"paramount":" Duty and Loyalty","less_significant":"Compassion"}},"derived":{"endurance":8,"composure":6,"focus":5,"vigilance":2,"void_points":2},"money":{"zeni":0,"koku":5,"bu":0},"advancements":[{"label":"Courtesy +1 (1 -> 2)","type":"skill","skill":"courtesy","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Government +1 (1 -> 2)","type":"skill","skill":"government","ring":"void","at_rank":1,"xp":4,"in_curriculum":true}],"techniques":[{"name":"Prey on the Weak","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"shuji","rank":2,"description":"<ul><li>Court is not a kind place, and a harsh word is no less cruel for being spoken softly and with perfect etiquette.</li><li>As a Scheme action, make a TN 1 Courtesy (Air) check targeting a Compromised character.</li><li>If you succeed, your target must choose one of the following: (1) Immediately unmask in a manner of their choosing based on the circumstances. (2) Forfeit glory equal to your Air Ring plus your bonus successes to leave the scene.</li><li>Air (op)+: If the target chooses to unmask, you learn one of their disadvantages of their choice per (op) spent this way.</li><li>Air (op)(op): If the target chooses to leave the scene, you notice their destination from the direction of their departure or overhear from the crowd where they will retreat.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":215},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.ekziVajOr3Up1EjP","skill":"courtesy"},{"name":"Commune with the Spirits","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"ritual","rank":1,"description":"<ul><li>The ritualist centers their mind on one of the Elements, appealing to the spirits in their environment and seeking their counsel or boon. Priests and laypeople are able to use this ritual to receive less specific guidance from the spirits, such as a leaf that falls to the ground pointing in the direction of the person or thing they are seeking.</li><li>As a downtime activity or Support action, make a TN 1 Theology check using Air, Earth, Fire, Water, or Void to appeal to nearby spirits of that Element (appeal to the departed, such as ancestor spirits, and other non-elemental supernatural presences if using Void) for aid.</li><li>If you succeed, choose and receive one of the following boons: (1) Sense the Kami — Detect all spirits and uses of their magic by shugenja within a number of range bands equal to the ring you used plus your bonus successes. (2) Spiritual Knowledge — Learn one fact the spirits know about the area. (3) Elemental Gift — The kami deliver a small amount of the Element in question to you (e.g., rain from water kami, sparks from fire kami, a gust from air kami, a stone from earth kami, or a found ancestor&#x27;s belonging from Void).</li><li>(op): Reduce the TN of your next check to interact with or appeal to kami or supernatural presences of this Element by 1.</li><li>(op)+: If you succeed, receive one additional boon per (op) spent this way. Each boon can only be received one time per activation.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":212},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-rituals-l5r-sortilege.Item.r9DyFb62vtLwexbW","skill":"theology"},{"name":"By the Light of the Lord Moon","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"invocation","rank":1,"description":"<ul><li>When a shugenja performs this invocation, the light shifts to that of a moonlit night, unweaving the shadows to lay bare the things they conceal. Hidden objects glow faintly with silver light, while mystical illusions are revealed as translucent, gossamer forms.</li><li>As a Scheme action, make a TN 2 Theology (Air) check targeting an area at range 0-2.</li><li>If you succeed, you scry for each hidden character and concealed object (secret compartments, trap doors, concealed weapons) in the targeted area, revealing it with a luminous outline only you can perceive. Only reveals mundane concealment.</li><li>Air +(op): Reveal up to one magically concealed object per (op) spent this way.</li><li>Air (op)(op)+: Choose one additional character at range 0-1 per (op)(op) spent this way who can also see the objects.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":192},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-invocations-l5r-sortilege.Item.X37l2OFmdoUXYJtX","skill":"theology"},{"name":"Cloak of Night","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"invocation","rank":1,"description":"<ul><li>A sufficiently learned shugenja can call forth air kami to play one of their simplest and most effective tricks: enveloping an object or person in their embrace to hide it from sight.</li><li>As a Scheme and Support action, make a Theology (Air) check targeting one object or character at range 0-1. TN equals the target&#x27;s Silhouette.</li><li>If you succeed, you augment the target with an illusion that renders it invisible to the naked eye. The object is still physically present and can be touched, smelled, or sensed with any normal sense other than vision. Persists for one round, plus additional rounds equal to your bonus successes.</li><li>Air (op)(op)+: Choose one additional target of the same silhouette or smaller per (op)(op) spent this way.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":192},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-invocations-l5r-sortilege.Item.fveOrp1xJ9uGnNCl","skill":"theology"},{"name":"Fukurokujin’s Wit","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"invocation","rank":1,"description":"<ul><li>Shujenja are scholars at their heart, for their art is one of long hours of study and dedication to the refinement of the mind. Thus, many seek the blessing of Fukurokujin, keeper of knowledge and patron to scholars. A shugenja can call upon the guidance of this Fortune to sharpen their mind to a razor edge and vitalize their nerves.</li><li>As a Support action, make a TN 1 Theology (Fire) check targeting yourself.</li><li>If you succeed, you augment your target&#x27;s wits and cunning. When making checks, the target adds a kept (ring) set to a (su) result. Persists for one round, plus additional rounds equal to bonus successes.</li><li>Fire (op): You may target another character at range 0-2 instead of yourself.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":203},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-invocations-l5r-sortilege.Item.bH76OcZ5FOcuLRXx","skill":"theology"},{"name":"Sudden Nightfall","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"school_ability","rank":1,"description":"<p>You do not suffer ill effects of Obscuring terrain from darkness. When you perform an Attack or Scheme action against a target in darkness-Obscuring terrain, reduce the TN by your school rank (minimum 1). As a Support action, summon supernatural darkness at range 0-2; area extending Air Ring range bands becomes Obscuring, persisting a number of rounds equal to school rank.</p>","text_source":"dsl","source":{"book":"celestial_realms","page":87},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.a06K6G42WcqlCnxQ"},{"name":"Deadly Sting","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"ninjutsu","rank":2,"description":"<ul><li>Poison is not a weapon an honorable samurai would choose, but it is tremendously effective, and like its namesake, the Scorpion Clan is not above envenoming its weapons to defeat foes it otherwise could not best.</li><li>As an Attack action, you may use one dose of a poison and make a TN 3 Martial Arts (Air) check using a readied Concealable weapon targeting one character within the weapon&#x27;s range.</li><li>If you succeed, apply the chosen poison to your weapon (see Poison). Then, the target suffers physical damage equal to the deadliness of your weapon plus your bonus successes.</li><li>Air (op): Move 1 range band.</li><li>Air (op)+: If you succeed, the target suffers a critical strike with severity 2, plus 1 per (op) spent this way.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":226},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-ninjitsu-l5r-sortilege.Item.9dRKaiSTJ9xnIdPK","skill":"melee,ranged,unarmed"},{"name":"Skulk","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"ninjutsu","rank":1,"description":"<ul><li>Shinobi are known for walking silently from shadow to shadow, moving like phantoms. Some of this relies upon agility and speed, of course, but veterans in the art of stealth know that using a crowd or another visual distraction to walk unnoticed can be as effective as the most complex acrobatics.</li><li>When you perform an Initiative or Attack check using Air, you may spend (op) as follows:</li><li>(op): If you are in Obscuring terrain, a crowd, or otherwise concealed from sight, one character with vigilance lower than or equal to your ranks in Skulduggery loses sight of you.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":226},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-ninjitsu-l5r-sortilege.Item.tKw2dMxzwVBuWOaT"},{"name":"Courtier’s Resolve","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"shuji","rank":1,"description":"<ul><li>Warriors do battle with their bodies, and courtiers do battle with their minds. To maintain one’s composure while surrounded by the challenges of court, one must be able to clear and organize one’s mind, returning focus to the most vital tasks.</li><li>Once per scene as a Support action, you may spend 1 Void point to recover from strife.</li><li>Remove strife equal to your glory rank.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":222},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.KaIqecu4b1TpXZid"},{"name":"Sensational Distraction","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"shuji","rank":1,"description":"<ul><li>Standing out in court requires a great deal of both cunning and flair, and standing out on purpose can be even harder. Courtiers train for much of their lives to learn to control the perceptions of others at court. The best courtiers know when to draw attention to themselves with a display of rhetorical prowess or another social feat and when to avoid attention. Drawing attention to oneself can give collaborators the chance to work unnoticed as well, and thus it is an extremely valuable tool in the courtier’s arsenal.</li><li>When making a Social skill (Fire) check targeting one or more characters, you may spend (op) in the following way:</li><li>Fire (op)+: When interacting with other characters, the target treats their vigilance as 1 lower per (op) spent this way; when interacting with you, the target treats their vigilance as 1 higher per (op) spent this way. This effect persists until the end of the scene.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":219},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.hYa08wHoU69Xu0GX"}],"peculiarities":[{"name":"Blackmail on Akodo Nobuhiko","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"fire","types":"Interpersonal","custom":true,"description":"<p><span class=\"fontstyle0\"><em>“I had hoped to find you here,” Yogo Hiroue began. “It has been too long since we last spoke plainly.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Blackmail on [Name] distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- You have incriminating information on an individual, which you use to force them to help you even when doing so may damage their reputation. They will share what knowledge they have about a given person, item, location, or situation, whether through a face-to-face meeting or through written correspondence. They will also arrange for introductions with exclusive members of society or places of business. Confer with the GM to select a campaign-appropriate NPC when choosing this advantage.</span></p></li><li><p><span class=\"fontstyle0\">- When performing a check to demand favors of the chosen individual (such as a Courtesy (fire) check to remind them of the consequences of their disobeying you or a Command (fire) check to order them to risk themself on your behalf), you may reroll up to two dice.</span></p></li></ul>","source_reference":{"source":"core_rulebook","page":102}},{"name":"Tea","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"passion","ring":"void","types":"Physical, Spiritual","description":"<ul><li>You can identify regional variations in tea, and you know a great deal about the process of preparing and drying leaves. In the wilderness, you can acquire the natural ingredients required to make rustic teas of various sorts with relative ease.</li><li>After performing a check to interact with tea (such as a Medicine [Void] check to brew a tea with ingredients that help the body recover from illness or a Performance [Void] check to perform a tea ceremony that helps the recipients contemplate their state in life), you remove 3 strife.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":115},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.wiz5rooMR3tqtULe"},{"name":"Shadowlands Taint (Air)","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"air","types":"Curse, Interpersonal, Spiritual","description":"<ul><li>You are a Tainted being. You have trouble sympathizing with other humans, but you can understand the emotions of corrupted beings easily.</li><li>When you make a check to show compassion for other human beings (such as a Composition [Air] check to edit a work for emotional refinement or a Courtesy [Air] check to say something difficult without harming the recipient&#x27;s feelings), you must choose and reroll two dice containing success or explosive success. After resolving the check, if you failed, you gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":127},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.eEg9b6rmnSBA5HqG"},{"name":"Conspiracy","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"anxiety","ring":"earth","types":"Interpersonal, Mental","description":"<ul><li>Plagued by knowledge of greater plots; you are constantly suspicious of authority figures.</li><li>After performing a check to interact with an unfamiliar authority figure, you receive 3 strife. If this is the first time this scene, gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"celestial_realms","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.wBeHgMqK2BL7fX6I"},{"name":"Disdain for Compassion","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"water","types":"Flaw, Mental","description":"<ul><li>Choose one tenet: Compassion (Water), Courage (Fire), Courtesy (Air), Duty and Loyalty (Earth), Honor (Void), Righteousness (Void), or Sincerity (Void). A character may have multiple instances of this disadvantage for different tenets. You no longer believe in the chosen tenet of Bushidō, though you still lose honor for disobeying it. When you act in accordance with this tenet of Bushidō, others can sometimes sense your insincerity.</li><li>When you make a check to pay lip service to this tenet of Bushidō or to uphold it (such as a Courtesy check to express its importance or a Meditation check to use a belief in this tenet to your advantage), you must choose and reroll two dice containing success or explosive success. After resolving the check, if you failed, you gain 1 Void point.</li></ul>","text_source":"dsl","text_via":"Disdain for a Bushidō Tenet","source":{"book":"core_rulebook","page":120},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.WLiIHkS6o7pS2u9y"},{"name":"Benten’s Curse","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"air","types":"Interpersonal, Spiritual","description":"<ul><li>Your romantic efforts are always stymied by circumstances, and your gestures to get the romantic attention of others are usually misinterpreted.</li><li>When you make a check to express your admiration to someone (such as an Aesthetics [Air] check to find the right poem to read to express your feelings or a Courtesy [Air] check to tell someone your feelings without exceeding propriety), you must choose and reroll two dice containing success or explosive success. After resolving the check, if you failed, you gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":116},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.wx0TwgTwrxGMVd1g"}],"titles":[],"bonds":[],"signature_scrolls":[],"gear":[{"name":"Wakizashi","quantity":1,"description":"<p>Whereas the katana represents a samurai’s status as a warrior, the wakizashi represents their place in Rokugan’s social order and strict caste system. The wakizashi is a small, katana-like sword usually two to three feet in length, with the same flexible blade and lethal edge. It is often made as part of a pair, with the same decorations as its matched katana. The wakizashi also fills another role: it clearly signals that its wearer is a samurai, and a person of honor who will make the ultimate sacrifice for their ideals and their master. It is the tool with which a samurai commits seppuku: ritual suicide, the last protest of an aggrieved and honorable samurai.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":233},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.S1MG4qPHEV3N8XnO","damage":3,"deadliness":5,"range":"0-1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"15 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Shuriken","quantity":6,"description":"<p>Favored by shinobi, shuriken are small metal discs with a sharpened edge that come in a dizzying array of sizes and styles. They are designed mainly to distract, but shuriken can also be coated with toxins for lethality, and any cutting edge can kill if used properly.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":237},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.5Lr1CNs1uvX7J38y","damage":2,"deadliness":4,"range":"0","grip_1":"(stab or slash): -, (thrown): Martial Arts [Ranged], Range 1-3","grip_2":"N/A","skill":"unarmed","category":"Specialist Weapons","rarity":"6","zeni":"1 koku","properties":[{"id":"L5RCorePro000005","name":"Concealable"}]},{"name":"Concealed Armor","quantity":1,"description":"<p>Used by cautious courtiers, shinobi, and anyone else who fears assassination, concealed armor is a kimono, keikogi, or other garment with thin bamboo or metal plates sewn inside to turn an unexpected blade or arrow.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.vDEAuVf0o5GwmVsB","armor":{"physical":2,"supernatural":0},"rarity":"4","zeni":"5 koku","properties":[{"id":"L5RCorePro000005","name":"Concealable"}]},{"name":"Sanctified Robes","quantity":1,"description":"<p>The vestments of shugenja, shrine keepers, and other religious figures are blessed by kami and thus grant mystical protection. Traditionally, such robes consist of a white garment called jōe (literally, “pure cloth”) and a peaked hat, but they can be simpler, such as a white haori top and red hakama bottoms, or even an elaborate kimono.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.Cq1koK56k9dvLfMh","armor":{"physical":1,"supernatural":3},"rarity":"7","zeni":"4 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"}]},{"name":"Poison (One Vial)","quantity":3,"description":"<p>In the courts of the Emerald Empire, the wheels of politics are sometimes turned by unsavory means. Members of the Scorpion Clan are certainly not above using poison to weaken or eliminate political rivals—not that one could ever prove their culpability—and many samurai turn to such measures in times of desperation or fear.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":244},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.SNTCLZ2aScPEddId","rarity":"5","zeni":"30 zeni","properties":[{"id":"L5RCorePro000009","name":"Forbidden"}]},{"name":"Tetsubishi","quantity":1,"description":"<ul><li>Category: Personal Effect</li><li>Cost: 5 bu per handful</li><li>Rarity: 4</li><li>As an Attack and Support action, a character may scatter a handful of tetsubishi targeting a patch of ground at range 0-2. The terrain at range 0-1 from the point of impact gains the Dangerous and Ensnaring terrain quality.</li></ul>","text_source":"dsl","source":{"book":"fields_of_victory","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.4OCDJyLlEF5F7feH","rarity":"4","zeni":"5 bu"},{"name":"Calligraphy Set","quantity":1,"description":"<p>These ornate boxes contain items a practiced callig- rapher needs to craft books, letters, scrolls, and other written communications. It consists of a small wooden box that contains a variety of brushes, inkstones, and pigments; a small bowl for water; and a small bag of sand for drying. Calligraphers and scribes customari- ly carry a calligraphy set, as so do some samurai and courtiers who prefer to write their own correspon- dence.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":242},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.MWzx5Wiu6xcCWc9J","rarity":"3","zeni":"1 bu"},{"name":"Personal Seal or Chop","quantity":1,"description":"<p>A personal chop is used by samurai to verify their iden- tity and sign documents, among other official business. Each one is a unique design that is registered with the Miya family. Using another samurai’s chop is consid- ered both an insult and a serious crime.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":243},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.UU5eQKPBQZ9ilOTF","rarity":"6","zeni":"4 bu","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"}]}],"gear_patterns":[]},{"xp":33,"label":"Interpreter, Rank 2","rank":2,"school":"Shosuro Shadowweaver School","foundry_id":"JVNV6v1nBOODVBs9","rings":{"air":2,"earth":1,"fire":3,"water":2,"void":2},"skills":{"artisan":{"aesthetics":0,"composition":2,"design":0,"smithing":0},"martial":{"fitness":0,"melee":0,"ranged":0,"unarmed":0,"meditation":1,"tactics":1},"scholar":{"culture":0,"government":3,"medicine":0,"sentiment":1,"theology":1},"social":{"command":1,"courtesy":2,"games":0,"performance":2},"trade":{"commerce":0,"labor":0,"seafaring":0,"skulduggery":2,"survival":0}},"social":{"honor":30,"glory":45,"status":32,"ninjo":"Kogo yearns for power that cannot be taken away by political whims or clan hierarchies. Deep down, she wants to transcend the petty limitations of clan politics entirely - to become something more than a samurai bound by duty and status.","giri":"Her lord is Nasu Tadaaki, her own father and current head of the declining Nasu family. Her duty is to restore the family's status and influence with the Imperial families. Kogo must prove the Nasu worthy of their former position.","bushido_tenets":{"paramount":" Duty and Loyalty","less_significant":"Compassion"}},"derived":{"endurance":8,"composure":6,"focus":5,"vigilance":2,"void_points":2},"money":{"zeni":0,"koku":5,"bu":0},"advancements":[{"label":"Courtesy +1 (1 -> 2)","type":"skill","skill":"courtesy","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Government +1 (1 -> 2)","type":"skill","skill":"government","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Performance +1 (1 -> 2)","type":"skill","skill":"performance","ring":"void","at_rank":1,"xp":4,"in_curriculum":true,"via":"Interpreter (Ivory Kingdoms)"},{"label":"Government +1 (2 -> 3)","type":"skill","skill":"government","ring":"void","at_rank":1,"xp":6,"in_curriculum":true,"via":"Interpreter (Ivory Kingdoms)"}],"techniques":[{"name":"Prey on the Weak","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"shuji","rank":2,"description":"<ul><li>Court is not a kind place, and a harsh word is no less cruel for being spoken softly and with perfect etiquette.</li><li>As a Scheme action, make a TN 1 Courtesy (Air) check targeting a Compromised character.</li><li>If you succeed, your target must choose one of the following: (1) Immediately unmask in a manner of their choosing based on the circumstances. (2) Forfeit glory equal to your Air Ring plus your bonus successes to leave the scene.</li><li>Air (op)+: If the target chooses to unmask, you learn one of their disadvantages of their choice per (op) spent this way.</li><li>Air (op)(op): If the target chooses to leave the scene, you notice their destination from the direction of their departure or overhear from the crowd where they will retreat.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":215},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.ekziVajOr3Up1EjP","skill":"courtesy"},{"name":"Commune with the Spirits","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"ritual","rank":1,"description":"<ul><li>The ritualist centers their mind on one of the Elements, appealing to the spirits in their environment and seeking their counsel or boon. Priests and laypeople are able to use this ritual to receive less specific guidance from the spirits, such as a leaf that falls to the ground pointing in the direction of the person or thing they are seeking.</li><li>As a downtime activity or Support action, make a TN 1 Theology check using Air, Earth, Fire, Water, or Void to appeal to nearby spirits of that Element (appeal to the departed, such as ancestor spirits, and other non-elemental supernatural presences if using Void) for aid.</li><li>If you succeed, choose and receive one of the following boons: (1) Sense the Kami — Detect all spirits and uses of their magic by shugenja within a number of range bands equal to the ring you used plus your bonus successes. (2) Spiritual Knowledge — Learn one fact the spirits know about the area. (3) Elemental Gift — The kami deliver a small amount of the Element in question to you (e.g., rain from water kami, sparks from fire kami, a gust from air kami, a stone from earth kami, or a found ancestor&#x27;s belonging from Void).</li><li>(op): Reduce the TN of your next check to interact with or appeal to kami or supernatural presences of this Element by 1.</li><li>(op)+: If you succeed, receive one additional boon per (op) spent this way. Each boon can only be received one time per activation.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":212},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-rituals-l5r-sortilege.Item.r9DyFb62vtLwexbW","skill":"theology"},{"name":"By the Light of the Lord Moon","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"invocation","rank":1,"description":"<ul><li>When a shugenja performs this invocation, the light shifts to that of a moonlit night, unweaving the shadows to lay bare the things they conceal. Hidden objects glow faintly with silver light, while mystical illusions are revealed as translucent, gossamer forms.</li><li>As a Scheme action, make a TN 2 Theology (Air) check targeting an area at range 0-2.</li><li>If you succeed, you scry for each hidden character and concealed object (secret compartments, trap doors, concealed weapons) in the targeted area, revealing it with a luminous outline only you can perceive. Only reveals mundane concealment.</li><li>Air +(op): Reveal up to one magically concealed object per (op) spent this way.</li><li>Air (op)(op)+: Choose one additional character at range 0-1 per (op)(op) spent this way who can also see the objects.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":192},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-invocations-l5r-sortilege.Item.X37l2OFmdoUXYJtX","skill":"theology"},{"name":"Cloak of Night","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"invocation","rank":1,"description":"<ul><li>A sufficiently learned shugenja can call forth air kami to play one of their simplest and most effective tricks: enveloping an object or person in their embrace to hide it from sight.</li><li>As a Scheme and Support action, make a Theology (Air) check targeting one object or character at range 0-1. TN equals the target&#x27;s Silhouette.</li><li>If you succeed, you augment the target with an illusion that renders it invisible to the naked eye. The object is still physically present and can be touched, smelled, or sensed with any normal sense other than vision. Persists for one round, plus additional rounds equal to your bonus successes.</li><li>Air (op)(op)+: Choose one additional target of the same silhouette or smaller per (op)(op) spent this way.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":192},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-invocations-l5r-sortilege.Item.fveOrp1xJ9uGnNCl","skill":"theology"},{"name":"Fukurokujin’s Wit","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"invocation","rank":1,"description":"<ul><li>Shujenja are scholars at their heart, for their art is one of long hours of study and dedication to the refinement of the mind. Thus, many seek the blessing of Fukurokujin, keeper of knowledge and patron to scholars. A shugenja can call upon the guidance of this Fortune to sharpen their mind to a razor edge and vitalize their nerves.</li><li>As a Support action, make a TN 1 Theology (Fire) check targeting yourself.</li><li>If you succeed, you augment your target&#x27;s wits and cunning. When making checks, the target adds a kept (ring) set to a (su) result. Persists for one round, plus additional rounds equal to bonus successes.</li><li>Fire (op): You may target another character at range 0-2 instead of yourself.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":203},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-invocations-l5r-sortilege.Item.bH76OcZ5FOcuLRXx","skill":"theology"},{"name":"Sudden Nightfall","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"school_ability","rank":1,"description":"<p>You do not suffer ill effects of Obscuring terrain from darkness. When you perform an Attack or Scheme action against a target in darkness-Obscuring terrain, reduce the TN by your school rank (minimum 1). As a Support action, summon supernatural darkness at range 0-2; area extending Air Ring range bands becomes Obscuring, persisting a number of rounds equal to school rank.</p>","text_source":"dsl","source":{"book":"celestial_realms","page":87},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.a06K6G42WcqlCnxQ"},{"name":"Deadly Sting","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"ninjutsu","rank":2,"description":"<ul><li>Poison is not a weapon an honorable samurai would choose, but it is tremendously effective, and like its namesake, the Scorpion Clan is not above envenoming its weapons to defeat foes it otherwise could not best.</li><li>As an Attack action, you may use one dose of a poison and make a TN 3 Martial Arts (Air) check using a readied Concealable weapon targeting one character within the weapon&#x27;s range.</li><li>If you succeed, apply the chosen poison to your weapon (see Poison). Then, the target suffers physical damage equal to the deadliness of your weapon plus your bonus successes.</li><li>Air (op): Move 1 range band.</li><li>Air (op)+: If you succeed, the target suffers a critical strike with severity 2, plus 1 per (op) spent this way.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":226},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-ninjitsu-l5r-sortilege.Item.9dRKaiSTJ9xnIdPK","skill":"melee,ranged,unarmed"},{"name":"Skulk","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"ninjutsu","rank":1,"description":"<ul><li>Shinobi are known for walking silently from shadow to shadow, moving like phantoms. Some of this relies upon agility and speed, of course, but veterans in the art of stealth know that using a crowd or another visual distraction to walk unnoticed can be as effective as the most complex acrobatics.</li><li>When you perform an Initiative or Attack check using Air, you may spend (op) as follows:</li><li>(op): If you are in Obscuring terrain, a crowd, or otherwise concealed from sight, one character with vigilance lower than or equal to your ranks in Skulduggery loses sight of you.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":226},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-ninjitsu-l5r-sortilege.Item.tKw2dMxzwVBuWOaT"},{"name":"Courtier’s Resolve","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"shuji","rank":1,"description":"<ul><li>Warriors do battle with their bodies, and courtiers do battle with their minds. To maintain one’s composure while surrounded by the challenges of court, one must be able to clear and organize one’s mind, returning focus to the most vital tasks.</li><li>Once per scene as a Support action, you may spend 1 Void point to recover from strife.</li><li>Remove strife equal to your glory rank.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":222},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.KaIqecu4b1TpXZid"},{"name":"Sensational Distraction","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"shuji","rank":1,"description":"<ul><li>Standing out in court requires a great deal of both cunning and flair, and standing out on purpose can be even harder. Courtiers train for much of their lives to learn to control the perceptions of others at court. The best courtiers know when to draw attention to themselves with a display of rhetorical prowess or another social feat and when to avoid attention. Drawing attention to oneself can give collaborators the chance to work unnoticed as well, and thus it is an extremely valuable tool in the courtier’s arsenal.</li><li>When making a Social skill (Fire) check targeting one or more characters, you may spend (op) in the following way:</li><li>Fire (op)+: When interacting with other characters, the target treats their vigilance as 1 lower per (op) spent this way; when interacting with you, the target treats their vigilance as 1 higher per (op) spent this way. This effect persists until the end of the scene.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":219},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.hYa08wHoU69Xu0GX"},{"name":"Cultural Exchange","via":"Interpreter (Ivory Kingdoms)","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"ritual","rank":1,"description":"<ul><li>Activation: As a downtime activity, you may make a TN 2 Culture (Fire) check to establish cultural fundamentals with someone from an unfamiliar culture. A number of characters up to your ranks in Culture can participate.</li><li>If you succeed, each participant learns something of value about the culture of each other participant. Even without a shared language, participants establish basic communication through gestures and learned words.</li><li>Opportunities: (op)(op): Reduce TN of checks using the Theorize approach by 1 until end of next scene.</li></ul>","text_source":"dsl","source":{"book":"children_of_the_five_winds","page":110},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-rituals-l5r-sortilege.Item.hVxCGeBdiHycrwSw","skill":"culture"},{"name":"Linguistic Liason","xp_used":3,"xp_cost":3,"in_curriculum":false,"bought_at_rank":2,"kind":"title_ability","rank":1,"description":"<p>You learn the languages of the group for which you are an interpreter. The first time you make a check to interact socially with a member of this group each encounter, reduce the TN by 1.</p>","text_source":"dsl","source":{"book":null,"page":0},"uuid":"Compendium.l5r5e-compendia-sortilege.title-abilities-l5r-sortilege.Item.QF5rWgOXVmHcXt8G"}],"peculiarities":[{"name":"Blackmail on Akodo Nobuhiko","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"fire","types":"Interpersonal","custom":true,"description":"<p><span class=\"fontstyle0\"><em>“I had hoped to find you here,” Yogo Hiroue began. “It has been too long since we last spoke plainly.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Blackmail on [Name] distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- You have incriminating information on an individual, which you use to force them to help you even when doing so may damage their reputation. They will share what knowledge they have about a given person, item, location, or situation, whether through a face-to-face meeting or through written correspondence. They will also arrange for introductions with exclusive members of society or places of business. Confer with the GM to select a campaign-appropriate NPC when choosing this advantage.</span></p></li><li><p><span class=\"fontstyle0\">- When performing a check to demand favors of the chosen individual (such as a Courtesy (fire) check to remind them of the consequences of their disobeying you or a Command (fire) check to order them to risk themself on your behalf), you may reroll up to two dice.</span></p></li></ul>","source_reference":{"source":"core_rulebook","page":102}},{"name":"Tea","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"passion","ring":"void","types":"Physical, Spiritual","description":"<ul><li>You can identify regional variations in tea, and you know a great deal about the process of preparing and drying leaves. In the wilderness, you can acquire the natural ingredients required to make rustic teas of various sorts with relative ease.</li><li>After performing a check to interact with tea (such as a Medicine [Void] check to brew a tea with ingredients that help the body recover from illness or a Performance [Void] check to perform a tea ceremony that helps the recipients contemplate their state in life), you remove 3 strife.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":115},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.wiz5rooMR3tqtULe"},{"name":"Shadowlands Taint (Air)","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"air","types":"Curse, Interpersonal, Spiritual","description":"<ul><li>You are a Tainted being. You have trouble sympathizing with other humans, but you can understand the emotions of corrupted beings easily.</li><li>When you make a check to show compassion for other human beings (such as a Composition [Air] check to edit a work for emotional refinement or a Courtesy [Air] check to say something difficult without harming the recipient&#x27;s feelings), you must choose and reroll two dice containing success or explosive success. After resolving the check, if you failed, you gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":127},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.eEg9b6rmnSBA5HqG"},{"name":"Conspiracy","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"anxiety","ring":"earth","types":"Interpersonal, Mental","description":"<ul><li>Plagued by knowledge of greater plots; you are constantly suspicious of authority figures.</li><li>After performing a check to interact with an unfamiliar authority figure, you receive 3 strife. If this is the first time this scene, gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"celestial_realms","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.wBeHgMqK2BL7fX6I"},{"name":"Disdain for Compassion","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"water","types":"Flaw, Mental","description":"<ul><li>Choose one tenet: Compassion (Water), Courage (Fire), Courtesy (Air), Duty and Loyalty (Earth), Honor (Void), Righteousness (Void), or Sincerity (Void). A character may have multiple instances of this disadvantage for different tenets. You no longer believe in the chosen tenet of Bushidō, though you still lose honor for disobeying it. When you act in accordance with this tenet of Bushidō, others can sometimes sense your insincerity.</li><li>When you make a check to pay lip service to this tenet of Bushidō or to uphold it (such as a Courtesy check to express its importance or a Meditation check to use a belief in this tenet to your advantage), you must choose and reroll two dice containing success or explosive success. After resolving the check, if you failed, you gain 1 Void point.</li></ul>","text_source":"dsl","text_via":"Disdain for a Bushidō Tenet","source":{"book":"core_rulebook","page":120},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.WLiIHkS6o7pS2u9y"},{"name":"Benten’s Curse","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"air","types":"Interpersonal, Spiritual","description":"<ul><li>Your romantic efforts are always stymied by circumstances, and your gestures to get the romantic attention of others are usually misinterpreted.</li><li>When you make a check to express your admiration to someone (such as an Aesthetics [Air] check to find the right poem to read to express your feelings or a Courtesy [Air] check to tell someone your feelings without exceeding propriety), you must choose and reroll two dice containing success or explosive success. After resolving the check, if you failed, you gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":116},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.wx0TwgTwrxGMVd1g"}],"titles":[{"name":"Interpreter (Ivory Kingdoms)","xp_used":13,"xp_cost":12,"in_curriculum":false,"bought_at_rank":2,"custom":true,"description":"<p><span class=\"fontstyle0\">Although many within Rokugan live their entire lives without thinking of the Empire’s neighbors, the truth is that many other civilizations touch upon the Emerald Empire in one way or another. Some, such as the Ivory Kingdoms, have contact by way of the shared danger that is the Shadowlands. Others, such as the Seikitsu of the northern mountains, exist much nearer geographically to Rokugan but are deeply distinct in culture and way of life. And as human cultures have different languages and customs, interpreters are often required to assist in situations where these groups interact.</span></p><p><span class=\"fontstyle0\">Interpreters are expected to become fluent not only in the languages of the people they study but also in the practices and cultural touchstones of those groups. They must be able not only to translate but also to transliterate, understanding and conveying intent beyond the literal meaning of the words. This makes becoming an excellent interpreter a challenging process, requiring not only language skills but also keen insight into human nature.</span></p><p><span class=\"fontstyle2\"><strong>Assigned By:</strong> </span><span class=\"fontstyle0\">The GM, after a character has gained an initial familiarity with another culture and desires to learn more.</span></p><p><span class=\"fontstyle2\"><strong>Status Award:</strong> </span><span class=\"fontstyle0\">+5</span></p><p><span class=\"fontstyle2\"><strong>Glory Award:</strong> </span><span class=\"fontstyle0\">+5</span></p><p><span class=\"fontstyle2\"><strong>Special:</strong> </span><span class=\"fontstyle0\">A character who has completed this title can be assigned it again for a new group. The new instance of the title counts as a different title, which can be completed again, conferring benefits for the new group selected.</span></p><p><span class=\"fontstyle2\"><strong>Title Ability:</strong> Linguistic Liaison</span></p><h2>Curriculum</h2><table><tbody><tr><td><p>Social Skills</p></td><td><p>Skill Group</p></td></tr><tr><td><p>Composition</p></td><td><p>Skill</p></td></tr><tr><td><p>Culture</p></td><td><p>Skill</p></td></tr><tr><td><p>Government</p></td><td><p>Skill</p></td></tr><tr><td><p><a class=\"compendium-link\" data-pack=\"l5r5e.core-techniques-shuji\">(shuji) Rank 1 Shuji</a> (prereq)</p></td><td><p>Tech. Grp.</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-rituals.Item.L5RCoreRit000037\" data-pack=\"l5r5e.core-techniques-rituals\" data-type=\"Item\" data-id=\"L5RCoreRit000037\">(ritual) Cultural Exchange</a> (prereq)</p></td><td><p>Technique</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-rituals.Item.L5RCoreRit000041\" data-pack=\"l5r5e.core-techniques-rituals\" data-type=\"Item\" data-id=\"L5RCoreRit000041\">(ritual) Traveler's Experience</a> (prereq)</p></td><td><p>Technique</p></td></tr></tbody></table>","source_reference":{"source":"children_of_the_five_winds","page":135}}],"bonds":[],"signature_scrolls":[],"gear":[{"name":"Wakizashi","quantity":1,"description":"<p>Whereas the katana represents a samurai’s status as a warrior, the wakizashi represents their place in Rokugan’s social order and strict caste system. The wakizashi is a small, katana-like sword usually two to three feet in length, with the same flexible blade and lethal edge. It is often made as part of a pair, with the same decorations as its matched katana. The wakizashi also fills another role: it clearly signals that its wearer is a samurai, and a person of honor who will make the ultimate sacrifice for their ideals and their master. It is the tool with which a samurai commits seppuku: ritual suicide, the last protest of an aggrieved and honorable samurai.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":233},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.S1MG4qPHEV3N8XnO","damage":3,"deadliness":5,"range":"0-1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"15 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Shuriken","quantity":6,"description":"<p>Favored by shinobi, shuriken are small metal discs with a sharpened edge that come in a dizzying array of sizes and styles. They are designed mainly to distract, but shuriken can also be coated with toxins for lethality, and any cutting edge can kill if used properly.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":237},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.5Lr1CNs1uvX7J38y","damage":2,"deadliness":4,"range":"0","grip_1":"(stab or slash): -, (thrown): Martial Arts [Ranged], Range 1-3","grip_2":"N/A","skill":"unarmed","category":"Specialist Weapons","rarity":"6","zeni":"1 koku","properties":[{"id":"L5RCorePro000005","name":"Concealable"}]},{"name":"Concealed Armor","quantity":1,"description":"<p>Used by cautious courtiers, shinobi, and anyone else who fears assassination, concealed armor is a kimono, keikogi, or other garment with thin bamboo or metal plates sewn inside to turn an unexpected blade or arrow.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.vDEAuVf0o5GwmVsB","armor":{"physical":2,"supernatural":0},"rarity":"4","zeni":"5 koku","properties":[{"id":"L5RCorePro000005","name":"Concealable"}]},{"name":"Sanctified Robes","quantity":1,"description":"<p>The vestments of shugenja, shrine keepers, and other religious figures are blessed by kami and thus grant mystical protection. Traditionally, such robes consist of a white garment called jōe (literally, “pure cloth”) and a peaked hat, but they can be simpler, such as a white haori top and red hakama bottoms, or even an elaborate kimono.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.Cq1koK56k9dvLfMh","armor":{"physical":1,"supernatural":3},"rarity":"7","zeni":"4 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"}]},{"name":"Poison (One Vial)","quantity":3,"description":"<p>In the courts of the Emerald Empire, the wheels of politics are sometimes turned by unsavory means. Members of the Scorpion Clan are certainly not above using poison to weaken or eliminate political rivals—not that one could ever prove their culpability—and many samurai turn to such measures in times of desperation or fear.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":244},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.SNTCLZ2aScPEddId","rarity":"5","zeni":"30 zeni","properties":[{"id":"L5RCorePro000009","name":"Forbidden"}]},{"name":"Tetsubishi","quantity":1,"description":"<ul><li>Category: Personal Effect</li><li>Cost: 5 bu per handful</li><li>Rarity: 4</li><li>As an Attack and Support action, a character may scatter a handful of tetsubishi targeting a patch of ground at range 0-2. The terrain at range 0-1 from the point of impact gains the Dangerous and Ensnaring terrain quality.</li></ul>","text_source":"dsl","source":{"book":"fields_of_victory","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.4OCDJyLlEF5F7feH","rarity":"4","zeni":"5 bu"},{"name":"Calligraphy Set","quantity":1,"description":"<p>These ornate boxes contain items a practiced callig- rapher needs to craft books, letters, scrolls, and other written communications. It consists of a small wooden box that contains a variety of brushes, inkstones, and pigments; a small bowl for water; and a small bag of sand for drying. Calligraphers and scribes customari- ly carry a calligraphy set, as so do some samurai and courtiers who prefer to write their own correspon- dence.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":242},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.MWzx5Wiu6xcCWc9J","rarity":"3","zeni":"1 bu"},{"name":"Personal Seal or Chop","quantity":1,"description":"<p>A personal chop is used by samurai to verify their iden- tity and sign documents, among other official business. Each one is a unique design that is registered with the Miya family. Using another samurai’s chop is consid- ered both an insult and a serious crime.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":243},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.UU5eQKPBQZ9ilOTF","rarity":"6","zeni":"4 bu","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"}]}],"gear_patterns":[]},{"xp":63,"label":"Interpreter, Rank 3","rank":3,"school":"Shosuro Shadowweaver School","foundry_id":"HhUYx9efAco0z2SQ","rings":{"air":2,"earth":1,"fire":3,"water":2,"void":2},"skills":{"artisan":{"aesthetics":0,"composition":2,"design":0,"smithing":0},"martial":{"fitness":0,"melee":0,"ranged":2,"unarmed":0,"meditation":1,"tactics":1},"scholar":{"culture":0,"government":3,"medicine":0,"sentiment":1,"theology":1},"social":{"command":1,"courtesy":2,"games":0,"performance":2},"trade":{"commerce":0,"labor":0,"seafaring":0,"skulduggery":2,"survival":0}},"social":{"honor":30,"glory":45,"status":32,"ninjo":"Kogo yearns for power that cannot be taken away by political whims or clan hierarchies. Deep down, she wants to transcend the petty limitations of clan politics entirely - to become something more than a samurai bound by duty and status.","giri":"Her lord is Nasu Tadaaki, her own father and current head of the declining Nasu family. Her duty is to restore the family's status and influence with the Imperial families. Kogo must prove the Nasu worthy of their former position.","bushido_tenets":{"paramount":" Duty and Loyalty","less_significant":"Compassion"}},"derived":{"endurance":8,"composure":6,"focus":5,"vigilance":2,"void_points":2},"money":{"zeni":0,"koku":5,"bu":0},"advancements":[{"label":"Courtesy +1 (1 -> 2)","type":"skill","skill":"courtesy","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Government +1 (1 -> 2)","type":"skill","skill":"government","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Performance +1 (1 -> 2)","type":"skill","skill":"performance","ring":"void","at_rank":1,"xp":4,"in_curriculum":true,"via":"Interpreter (Ivory Kingdoms)"},{"label":"Government +1 (2 -> 3)","type":"skill","skill":"government","ring":"void","at_rank":1,"xp":6,"in_curriculum":true,"via":"Interpreter (Ivory Kingdoms)"},{"label":"Martial Arts [Ranged] +1 (0 -> 1)","type":"skill","skill":"ranged","ring":"void","at_rank":2,"xp":2,"in_curriculum":true},{"label":"Martial Arts [Ranged] +1 (1 -> 2)","type":"skill","skill":"ranged","ring":"void","at_rank":2,"xp":4,"in_curriculum":true}],"techniques":[{"name":"Prey on the Weak","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"shuji","rank":2,"description":"<ul><li>Court is not a kind place, and a harsh word is no less cruel for being spoken softly and with perfect etiquette.</li><li>As a Scheme action, make a TN 1 Courtesy (Air) check targeting a Compromised character.</li><li>If you succeed, your target must choose one of the following: (1) Immediately unmask in a manner of their choosing based on the circumstances. (2) Forfeit glory equal to your Air Ring plus your bonus successes to leave the scene.</li><li>Air (op)+: If the target chooses to unmask, you learn one of their disadvantages of their choice per (op) spent this way.</li><li>Air (op)(op): If the target chooses to leave the scene, you notice their destination from the direction of their departure or overhear from the crowd where they will retreat.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":215},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.ekziVajOr3Up1EjP","skill":"courtesy"},{"name":"Commune with the Spirits","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"ritual","rank":1,"description":"<ul><li>The ritualist centers their mind on one of the Elements, appealing to the spirits in their environment and seeking their counsel or boon. Priests and laypeople are able to use this ritual to receive less specific guidance from the spirits, such as a leaf that falls to the ground pointing in the direction of the person or thing they are seeking.</li><li>As a downtime activity or Support action, make a TN 1 Theology check using Air, Earth, Fire, Water, or Void to appeal to nearby spirits of that Element (appeal to the departed, such as ancestor spirits, and other non-elemental supernatural presences if using Void) for aid.</li><li>If you succeed, choose and receive one of the following boons: (1) Sense the Kami — Detect all spirits and uses of their magic by shugenja within a number of range bands equal to the ring you used plus your bonus successes. (2) Spiritual Knowledge — Learn one fact the spirits know about the area. (3) Elemental Gift — The kami deliver a small amount of the Element in question to you (e.g., rain from water kami, sparks from fire kami, a gust from air kami, a stone from earth kami, or a found ancestor&#x27;s belonging from Void).</li><li>(op): Reduce the TN of your next check to interact with or appeal to kami or supernatural presences of this Element by 1.</li><li>(op)+: If you succeed, receive one additional boon per (op) spent this way. Each boon can only be received one time per activation.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":212},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-rituals-l5r-sortilege.Item.r9DyFb62vtLwexbW","skill":"theology"},{"name":"By the Light of the Lord Moon","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"invocation","rank":1,"description":"<ul><li>When a shugenja performs this invocation, the light shifts to that of a moonlit night, unweaving the shadows to lay bare the things they conceal. Hidden objects glow faintly with silver light, while mystical illusions are revealed as translucent, gossamer forms.</li><li>As a Scheme action, make a TN 2 Theology (Air) check targeting an area at range 0-2.</li><li>If you succeed, you scry for each hidden character and concealed object (secret compartments, trap doors, concealed weapons) in the targeted area, revealing it with a luminous outline only you can perceive. Only reveals mundane concealment.</li><li>Air +(op): Reveal up to one magically concealed object per (op) spent this way.</li><li>Air (op)(op)+: Choose one additional character at range 0-1 per (op)(op) spent this way who can also see the objects.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":192},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-invocations-l5r-sortilege.Item.X37l2OFmdoUXYJtX","skill":"theology"},{"name":"Cloak of Night","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"invocation","rank":1,"description":"<ul><li>A sufficiently learned shugenja can call forth air kami to play one of their simplest and most effective tricks: enveloping an object or person in their embrace to hide it from sight.</li><li>As a Scheme and Support action, make a Theology (Air) check targeting one object or character at range 0-1. TN equals the target&#x27;s Silhouette.</li><li>If you succeed, you augment the target with an illusion that renders it invisible to the naked eye. The object is still physically present and can be touched, smelled, or sensed with any normal sense other than vision. Persists for one round, plus additional rounds equal to your bonus successes.</li><li>Air (op)(op)+: Choose one additional target of the same silhouette or smaller per (op)(op) spent this way.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":192},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-invocations-l5r-sortilege.Item.fveOrp1xJ9uGnNCl","skill":"theology"},{"name":"Fukurokujin’s Wit","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"invocation","rank":1,"description":"<ul><li>Shujenja are scholars at their heart, for their art is one of long hours of study and dedication to the refinement of the mind. Thus, many seek the blessing of Fukurokujin, keeper of knowledge and patron to scholars. A shugenja can call upon the guidance of this Fortune to sharpen their mind to a razor edge and vitalize their nerves.</li><li>As a Support action, make a TN 1 Theology (Fire) check targeting yourself.</li><li>If you succeed, you augment your target&#x27;s wits and cunning. When making checks, the target adds a kept (ring) set to a (su) result. Persists for one round, plus additional rounds equal to bonus successes.</li><li>Fire (op): You may target another character at range 0-2 instead of yourself.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":203},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-invocations-l5r-sortilege.Item.bH76OcZ5FOcuLRXx","skill":"theology"},{"name":"Sudden Nightfall","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"school_ability","rank":1,"description":"<p>You do not suffer ill effects of Obscuring terrain from darkness. When you perform an Attack or Scheme action against a target in darkness-Obscuring terrain, reduce the TN by your school rank (minimum 1). As a Support action, summon supernatural darkness at range 0-2; area extending Air Ring range bands becomes Obscuring, persisting a number of rounds equal to school rank.</p>","text_source":"dsl","source":{"book":"celestial_realms","page":87},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.a06K6G42WcqlCnxQ"},{"name":"Deadly Sting","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"ninjutsu","rank":2,"description":"<ul><li>Poison is not a weapon an honorable samurai would choose, but it is tremendously effective, and like its namesake, the Scorpion Clan is not above envenoming its weapons to defeat foes it otherwise could not best.</li><li>As an Attack action, you may use one dose of a poison and make a TN 3 Martial Arts (Air) check using a readied Concealable weapon targeting one character within the weapon&#x27;s range.</li><li>If you succeed, apply the chosen poison to your weapon (see Poison). Then, the target suffers physical damage equal to the deadliness of your weapon plus your bonus successes.</li><li>Air (op): Move 1 range band.</li><li>Air (op)+: If you succeed, the target suffers a critical strike with severity 2, plus 1 per (op) spent this way.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":226},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-ninjitsu-l5r-sortilege.Item.9dRKaiSTJ9xnIdPK","skill":"melee,ranged,unarmed"},{"name":"Skulk","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"ninjutsu","rank":1,"description":"<ul><li>Shinobi are known for walking silently from shadow to shadow, moving like phantoms. Some of this relies upon agility and speed, of course, but veterans in the art of stealth know that using a crowd or another visual distraction to walk unnoticed can be as effective as the most complex acrobatics.</li><li>When you perform an Initiative or Attack check using Air, you may spend (op) as follows:</li><li>(op): If you are in Obscuring terrain, a crowd, or otherwise concealed from sight, one character with vigilance lower than or equal to your ranks in Skulduggery loses sight of you.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":226},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-ninjitsu-l5r-sortilege.Item.tKw2dMxzwVBuWOaT"},{"name":"Courtier’s Resolve","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"shuji","rank":1,"description":"<ul><li>Warriors do battle with their bodies, and courtiers do battle with their minds. To maintain one’s composure while surrounded by the challenges of court, one must be able to clear and organize one’s mind, returning focus to the most vital tasks.</li><li>Once per scene as a Support action, you may spend 1 Void point to recover from strife.</li><li>Remove strife equal to your glory rank.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":222},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.KaIqecu4b1TpXZid"},{"name":"Sensational Distraction","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"shuji","rank":1,"description":"<ul><li>Standing out in court requires a great deal of both cunning and flair, and standing out on purpose can be even harder. Courtiers train for much of their lives to learn to control the perceptions of others at court. The best courtiers know when to draw attention to themselves with a display of rhetorical prowess or another social feat and when to avoid attention. Drawing attention to oneself can give collaborators the chance to work unnoticed as well, and thus it is an extremely valuable tool in the courtier’s arsenal.</li><li>When making a Social skill (Fire) check targeting one or more characters, you may spend (op) in the following way:</li><li>Fire (op)+: When interacting with other characters, the target treats their vigilance as 1 lower per (op) spent this way; when interacting with you, the target treats their vigilance as 1 higher per (op) spent this way. This effect persists until the end of the scene.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":219},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.hYa08wHoU69Xu0GX"},{"name":"Cultural Exchange","via":"Interpreter (Ivory Kingdoms)","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"ritual","rank":1,"description":"<ul><li>Activation: As a downtime activity, you may make a TN 2 Culture (Fire) check to establish cultural fundamentals with someone from an unfamiliar culture. A number of characters up to your ranks in Culture can participate.</li><li>If you succeed, each participant learns something of value about the culture of each other participant. Even without a shared language, participants establish basic communication through gestures and learned words.</li><li>Opportunities: (op)(op): Reduce TN of checks using the Theorize approach by 1 until end of next scene.</li></ul>","text_source":"dsl","source":{"book":"children_of_the_five_winds","page":110},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-rituals-l5r-sortilege.Item.hVxCGeBdiHycrwSw","skill":"culture"},{"name":"Linguistic Liason","xp_used":3,"xp_cost":3,"in_curriculum":false,"bought_at_rank":2,"kind":"title_ability","rank":1,"description":"<p>You learn the languages of the group for which you are an interpreter. The first time you make a check to interact socially with a member of this group each encounter, reduce the TN by 1.</p>","text_source":"dsl","source":{"book":null,"page":0},"uuid":"Compendium.l5r5e-compendia-sortilege.title-abilities-l5r-sortilege.Item.QF5rWgOXVmHcXt8G"},{"name":"Commune with Evil","xp_used":3,"xp_cost":3,"in_curriculum":false,"bought_at_rank":2,"kind":"maho","rank":1,"description":"<ul><li>The practitioner detects any malevolent supernatural entities in the area, senses their desires, and makes a bargain for an unholy blessing.</li><li>Activation: As a downtime activity action, you may make a TN 1 Theology (Void) check.</li><li>If you succeed, you scry for the presence of any Otherworldly or Tainted beings at range 0–6.</li><li>Opportunities: (op): If there are any such beings, they accept your offering, and they augment you with an unholy blessing that increases the value of the ring you used for the check by 1. You can only have one unholy blessing at a time, and it persists until the end of the next scene. (op)(op)(op)+: If you receive an unholy blessing, it temporarily increases the ring&#x27;s value by an additional 1 per (op)(op)(op) spent this way. (op)+: If you receive an unholy blessing, it persists for 1 additional scene per (op) spent this way.</li></ul>","text_source":"dsl","source":{"book":"shadowlands","page":118},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-maho-l5r-sortilege.Item.XXHWw0ydoD5ktFR3","skill":"theology"},{"name":"Incite Haunting","xp_used":3,"xp_cost":3,"in_curriculum":false,"bought_at_rank":2,"kind":"maho","rank":1,"description":"<ul><li>Kansen are kami twisted by the power of Fu Leng, and they need little prompting to cause harm. Directing them toward a target with a vile rite and profane words that seem to warp the air, the mahō-tsukai afflicts a poor soul with a spiritual malady that can fester and bloom, fueling darker curses still. Spiritualists can perceive kansen as wretched, ghostly figures, clinging to their victim and dragging them inexorably toward a wretched end wrought by their worst nature.</li><li>As an Attack and Scheme action, make a Theology check targeting one character at range 0-1. This check uses any ring of your choice, and the TN of the check is equal to the target&#x27;s vigilance.</li><li>If you succeed, you curse your target, causing them to suffer the Afflicted condition. If you fail, the target rebuffs your efforts. If your shortfall is 2 or higher, the target also becomes aware of your attempted malediction.</li><li>(op)+: Treat the maximum range of the technique as 1 higher per (op) spent this way.</li><li>(op)+: Choose one additional target per (op) spent this way.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":224},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-maho-l5r-sortilege.Item.GsIvHMI0O2s07ypl","skill":"theology"},{"name":"Sinful Whispers","xp_used":3,"xp_cost":3,"in_curriculum":false,"bought_at_rank":2,"kind":"maho","rank":1,"description":"<ul><li>The kansen assail the victim’s mind, murmuring dark things that slowly erode their concentration, making them more receptive to the words of the mahō-tsukai and less able to think coherently.</li><li>As an Attack and Scheme action, make a Theology (Air) check targeting one character with the Afflicted condition at range 0-4. The TN of the check is equal to the target&#x27;s vigilance.</li><li>If you succeed, you curse your target, sapping their will; they must answer your questions honestly (and find doing so unremarkable at the time). This effect persists for a number of rounds equal to your Air Ring.</li><li>Air (op): The target does not remember what you asked, even if prompted to think about the conversation later.</li><li>Air (op)(op)(op): You may give the target a single simple order. The target may ignore that order, but receives 2 strife at the end of each scene in which they disregard it. When the target becomes Compromised, they must unmask and attempt to fulfill the order until the end of the scene.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":225},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-maho-l5r-sortilege.Item.Wlqbwh2FX0QpEUDU","skill":"theology"},{"name":"Unholy Fervor","xp_used":3,"xp_cost":3,"in_curriculum":false,"bought_at_rank":2,"kind":"maho","rank":1,"description":"<ul><li>The kansen bite and tear the flesh of the victim, wracking them with pain that transforms into mindless fury.</li><li>As a Support action, make a Theology (Fire) check targeting one character at range 0-3. The TN of this check is equal to the target&#x27;s vigilance.</li><li>If you succeed, you curse the target with blinding fury; they suffer the Enraged condition. You also augment the target&#x27;s corruption; they may treat each of their Shadowlands Taint disadvantages as an advantage that applies to any checks using its ring. This effect persists until the end of the scene.</li><li>Fire (op): Each target receives strife equal to your Fire Ring and removes that much fatigue.</li><li>Fire (op)+: Choose one additional target per (op) spent this way.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":225},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-maho-l5r-sortilege.Item.Y36kLAUCpuiSxSD7","skill":"theology"},{"name":"Accursed Summoning","xp_used":3,"xp_cost":3,"in_curriculum":false,"bought_at_rank":2,"kind":"maho","rank":1,"description":"<ul><li>Rank: 1</li><li>The mahō-tsukai spills blood and recites a foul prayer to summon a chosen oni and bind it to their will. The oni appears caught in an invisible prison, unable to act except at the summoner&#x27;s direction.</li><li>XP Cost: 3</li><li>Activation: As a downtime activity action, you may make a Theology (Void) check with TN equal to the oni&#x27;s Intrigue rank.</li><li>If you succeed, you summon the desired oni and bind it to your will, unable to act without your consent. If you fail, you summon the desired oni (or a different one, at the GM&#x27;s discretion) but it breaks free of your control and curses you, causing you to suffer the Afflicted condition. If you have 3 or more kept (ring) results, the summoned oni scries and learns your name.</li><li>Opportunities: (op)+: The sight of the oni instills primal terror in any onlookers. Each character who can see the oni and is within range 3 suffers a number of strife equal to (op) spent this way. (op)(op): The oni instills a Shadowlands Taint disadvantage of your choice upon anyone within a range equal to the number of your rings with the Shadowlands Taint disadvantage attached.</li></ul>","text_source":"dsl","source":{"book":"shadowlands","page":118},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-maho-l5r-sortilege.Item.NFND9NcuM2omMQpD","skill":"theology"},{"name":"Lord Bayushi’s Whispers (Scorpion)","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"shuji","rank":2,"description":"<ul><li>The Kami Bayushi, self-appointed villain of the Emperor Hantei and master of duplicity, founded the Scorpion Clan with a simple purpose: to dishonor themselves so that others could live honorably. Bayushi maintained vast networks of spies and informants, and he was extremely skilled at turning assets others used to try to spy on him. The Scorpion Clan has carried on this tradition with an efficiency that would surely make Bayushi proud. Hardly a town exists in the Empire without an agent of the Scorpion.</li><li>Once per game session, during a narrative scene or as a downtime activity, make a TN 2 Skulduggery (Void) check to uncover an informant who can give you information about a subject.</li><li>If you succeed, you reveal one informant who can give you information about a topic of your choice. If the informant&#x27;s profile is required, use an appropriate NPC of the GM&#x27;s choice.</li><li>Void (op): If you succeed, choose one skill. The informant has a number of ranks in that skill equal to your school rank and can perform checks with that skill to assist you until the end of the scene.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":223},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.zsXZtTrofBlj3FYg","skill":"skulduggery"},{"name":"Fluid Shadows","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"invocation","rank":2,"description":"<ul><li>Activation: Movement and Scheme action, TN 2 Theology (Water), target shadowy position at range 1-3</li><li>Summon yourself instantly to target position</li></ul>","text_source":"dsl","source":{"book":"celestial_realms","page":108},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-invocations-l5r-sortilege.Item.l05XM6wPSsXeLWhg","skill":"theology"}],"peculiarities":[{"name":"Blackmail on Akodo Nobuhiko","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"fire","types":"Interpersonal","custom":true,"description":"<p><span class=\"fontstyle0\"><em>“I had hoped to find you here,” Yogo Hiroue began. “It has been too long since we last spoke plainly.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Blackmail on [Name] distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- You have incriminating information on an individual, which you use to force them to help you even when doing so may damage their reputation. They will share what knowledge they have about a given person, item, location, or situation, whether through a face-to-face meeting or through written correspondence. They will also arrange for introductions with exclusive members of society or places of business. Confer with the GM to select a campaign-appropriate NPC when choosing this advantage.</span></p></li><li><p><span class=\"fontstyle0\">- When performing a check to demand favors of the chosen individual (such as a Courtesy (fire) check to remind them of the consequences of their disobeying you or a Command (fire) check to order them to risk themself on your behalf), you may reroll up to two dice.</span></p></li></ul>","source_reference":{"source":"core_rulebook","page":102}},{"name":"Tea","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"passion","ring":"void","types":"Physical, Spiritual","description":"<ul><li>You can identify regional variations in tea, and you know a great deal about the process of preparing and drying leaves. In the wilderness, you can acquire the natural ingredients required to make rustic teas of various sorts with relative ease.</li><li>After performing a check to interact with tea (such as a Medicine [Void] check to brew a tea with ingredients that help the body recover from illness or a Performance [Void] check to perform a tea ceremony that helps the recipients contemplate their state in life), you remove 3 strife.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":115},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.wiz5rooMR3tqtULe"},{"name":"Shadowlands Taint (Air)","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"air","types":"Curse, Interpersonal, Spiritual","description":"<ul><li>You are a Tainted being. You have trouble sympathizing with other humans, but you can understand the emotions of corrupted beings easily.</li><li>When you make a check to show compassion for other human beings (such as a Composition [Air] check to edit a work for emotional refinement or a Courtesy [Air] check to say something difficult without harming the recipient&#x27;s feelings), you must choose and reroll two dice containing success or explosive success. After resolving the check, if you failed, you gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":127},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.eEg9b6rmnSBA5HqG"},{"name":"Conspiracy","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"anxiety","ring":"earth","types":"Interpersonal, Mental","description":"<ul><li>Plagued by knowledge of greater plots; you are constantly suspicious of authority figures.</li><li>After performing a check to interact with an unfamiliar authority figure, you receive 3 strife. If this is the first time this scene, gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"celestial_realms","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.wBeHgMqK2BL7fX6I"},{"name":"Disdain for Compassion","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"water","types":"Flaw, Mental","description":"<ul><li>Choose one tenet: Compassion (Water), Courage (Fire), Courtesy (Air), Duty and Loyalty (Earth), Honor (Void), Righteousness (Void), or Sincerity (Void). A character may have multiple instances of this disadvantage for different tenets. You no longer believe in the chosen tenet of Bushidō, though you still lose honor for disobeying it. When you act in accordance with this tenet of Bushidō, others can sometimes sense your insincerity.</li><li>When you make a check to pay lip service to this tenet of Bushidō or to uphold it (such as a Courtesy check to express its importance or a Meditation check to use a belief in this tenet to your advantage), you must choose and reroll two dice containing success or explosive success. After resolving the check, if you failed, you gain 1 Void point.</li></ul>","text_source":"dsl","text_via":"Disdain for a Bushidō Tenet","source":{"book":"core_rulebook","page":120},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.WLiIHkS6o7pS2u9y"},{"name":"Benten’s Curse","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"air","types":"Interpersonal, Spiritual","description":"<ul><li>Your romantic efforts are always stymied by circumstances, and your gestures to get the romantic attention of others are usually misinterpreted.</li><li>When you make a check to express your admiration to someone (such as an Aesthetics [Air] check to find the right poem to read to express your feelings or a Courtesy [Air] check to tell someone your feelings without exceeding propriety), you must choose and reroll two dice containing success or explosive success. After resolving the check, if you failed, you gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":116},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.wx0TwgTwrxGMVd1g"}],"titles":[{"name":"Interpreter (Ivory Kingdoms)","xp_used":13,"xp_cost":12,"in_curriculum":false,"bought_at_rank":2,"custom":true,"description":"<p><span class=\"fontstyle0\">Although many within Rokugan live their entire lives without thinking of the Empire’s neighbors, the truth is that many other civilizations touch upon the Emerald Empire in one way or another. Some, such as the Ivory Kingdoms, have contact by way of the shared danger that is the Shadowlands. Others, such as the Seikitsu of the northern mountains, exist much nearer geographically to Rokugan but are deeply distinct in culture and way of life. And as human cultures have different languages and customs, interpreters are often required to assist in situations where these groups interact.</span></p><p><span class=\"fontstyle0\">Interpreters are expected to become fluent not only in the languages of the people they study but also in the practices and cultural touchstones of those groups. They must be able not only to translate but also to transliterate, understanding and conveying intent beyond the literal meaning of the words. This makes becoming an excellent interpreter a challenging process, requiring not only language skills but also keen insight into human nature.</span></p><p><span class=\"fontstyle2\"><strong>Assigned By:</strong> </span><span class=\"fontstyle0\">The GM, after a character has gained an initial familiarity with another culture and desires to learn more.</span></p><p><span class=\"fontstyle2\"><strong>Status Award:</strong> </span><span class=\"fontstyle0\">+5</span></p><p><span class=\"fontstyle2\"><strong>Glory Award:</strong> </span><span class=\"fontstyle0\">+5</span></p><p><span class=\"fontstyle2\"><strong>Special:</strong> </span><span class=\"fontstyle0\">A character who has completed this title can be assigned it again for a new group. The new instance of the title counts as a different title, which can be completed again, conferring benefits for the new group selected.</span></p><p><span class=\"fontstyle2\"><strong>Title Ability:</strong> Linguistic Liaison</span></p><h2>Curriculum</h2><table><tbody><tr><td><p>Social Skills</p></td><td><p>Skill Group</p></td></tr><tr><td><p>Composition</p></td><td><p>Skill</p></td></tr><tr><td><p>Culture</p></td><td><p>Skill</p></td></tr><tr><td><p>Government</p></td><td><p>Skill</p></td></tr><tr><td><p><a class=\"compendium-link\" data-pack=\"l5r5e.core-techniques-shuji\">(shuji) Rank 1 Shuji</a> (prereq)</p></td><td><p>Tech. Grp.</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-rituals.Item.L5RCoreRit000037\" data-pack=\"l5r5e.core-techniques-rituals\" data-type=\"Item\" data-id=\"L5RCoreRit000037\">(ritual) Cultural Exchange</a> (prereq)</p></td><td><p>Technique</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-rituals.Item.L5RCoreRit000041\" data-pack=\"l5r5e.core-techniques-rituals\" data-type=\"Item\" data-id=\"L5RCoreRit000041\">(ritual) Traveler's Experience</a> (prereq)</p></td><td><p>Technique</p></td></tr></tbody></table>","source_reference":{"source":"children_of_the_five_winds","page":135}}],"bonds":[],"signature_scrolls":[],"gear":[{"name":"Wakizashi","quantity":1,"description":"<p>Whereas the katana represents a samurai’s status as a warrior, the wakizashi represents their place in Rokugan’s social order and strict caste system. The wakizashi is a small, katana-like sword usually two to three feet in length, with the same flexible blade and lethal edge. It is often made as part of a pair, with the same decorations as its matched katana. The wakizashi also fills another role: it clearly signals that its wearer is a samurai, and a person of honor who will make the ultimate sacrifice for their ideals and their master. It is the tool with which a samurai commits seppuku: ritual suicide, the last protest of an aggrieved and honorable samurai.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":233},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.S1MG4qPHEV3N8XnO","damage":3,"deadliness":5,"range":"0-1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"15 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Shuriken","quantity":6,"description":"<p>Favored by shinobi, shuriken are small metal discs with a sharpened edge that come in a dizzying array of sizes and styles. They are designed mainly to distract, but shuriken can also be coated with toxins for lethality, and any cutting edge can kill if used properly.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":237},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.5Lr1CNs1uvX7J38y","damage":2,"deadliness":4,"range":"0","grip_1":"(stab or slash): -, (thrown): Martial Arts [Ranged], Range 1-3","grip_2":"N/A","skill":"unarmed","category":"Specialist Weapons","rarity":"6","zeni":"1 koku","properties":[{"id":"L5RCorePro000005","name":"Concealable"}]},{"name":"Concealed Armor","quantity":1,"description":"<p>Used by cautious courtiers, shinobi, and anyone else who fears assassination, concealed armor is a kimono, keikogi, or other garment with thin bamboo or metal plates sewn inside to turn an unexpected blade or arrow.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.vDEAuVf0o5GwmVsB","armor":{"physical":2,"supernatural":0},"rarity":"4","zeni":"5 koku","properties":[{"id":"L5RCorePro000005","name":"Concealable"}]},{"name":"Sanctified Robes","quantity":1,"description":"<p>The vestments of shugenja, shrine keepers, and other religious figures are blessed by kami and thus grant mystical protection. Traditionally, such robes consist of a white garment called jōe (literally, “pure cloth”) and a peaked hat, but they can be simpler, such as a white haori top and red hakama bottoms, or even an elaborate kimono.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.Cq1koK56k9dvLfMh","armor":{"physical":1,"supernatural":3},"rarity":"7","zeni":"4 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"}]},{"name":"Poison (One Vial)","quantity":3,"description":"<p>In the courts of the Emerald Empire, the wheels of politics are sometimes turned by unsavory means. Members of the Scorpion Clan are certainly not above using poison to weaken or eliminate political rivals—not that one could ever prove their culpability—and many samurai turn to such measures in times of desperation or fear.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":244},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.SNTCLZ2aScPEddId","rarity":"5","zeni":"30 zeni","properties":[{"id":"L5RCorePro000009","name":"Forbidden"}]},{"name":"Tetsubishi","quantity":1,"description":"<ul><li>Category: Personal Effect</li><li>Cost: 5 bu per handful</li><li>Rarity: 4</li><li>As an Attack and Support action, a character may scatter a handful of tetsubishi targeting a patch of ground at range 0-2. The terrain at range 0-1 from the point of impact gains the Dangerous and Ensnaring terrain quality.</li></ul>","text_source":"dsl","source":{"book":"fields_of_victory","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.4OCDJyLlEF5F7feH","rarity":"4","zeni":"5 bu"},{"name":"Calligraphy Set","quantity":1,"description":"<p>These ornate boxes contain items a practiced callig- rapher needs to craft books, letters, scrolls, and other written communications. It consists of a small wooden box that contains a variety of brushes, inkstones, and pigments; a small bowl for water; and a small bag of sand for drying. Calligraphers and scribes customari- ly carry a calligraphy set, as so do some samurai and courtiers who prefer to write their own correspon- dence.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":242},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.MWzx5Wiu6xcCWc9J","rarity":"3","zeni":"1 bu"},{"name":"Personal Seal or Chop","quantity":1,"description":"<p>A personal chop is used by samurai to verify their iden- tity and sign documents, among other official business. Each one is a unique design that is registered with the Miya family. Using another samurai’s chop is consid- ered both an insult and a serious crime.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":243},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.UU5eQKPBQZ9ilOTF","rarity":"6","zeni":"4 bu","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"}]}],"gear_patterns":[]}]};
